code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            # Fill the open-topped container and its gap with color 2.
            for x in range(left + 1, right):
                if grid[top][x] == 0:
                    out[top][x] = 2
            for y in range(top + 1, bottom):
                for x in range(left + 1, right):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            # The overflow runs leftward from the opening along the row above.
            if top > 0:
                opening = next((x for x in range(left + 1, right) if grid[top][x] == 0), None)
                if opening is not None:
                    for x in range(0, opening + 1):
                        if grid[top - 1][x] == 0:
                            out[top - 1][x] = 2
    return out
'''
